programs.gaussian:
data {
  int<lower=1> d;
  vector<lower=0>[d] scales;
}
parameters {
  vector[d] q;
}
model {
  target += -0.5 * dot_self(q ./ scales);
}

programs.banana:
data {
  real bend;
}
parameters {
  vector[2] q;
}
model {
  target += -0.5 * (square(q[1]) + square(q[2] - bend * (square(q[1]) - 1)));
}
